import React from 'react';
import { motion } from 'framer-motion';

const Resume = () => {
  const workExperience = [
    {
      title: 'Senior Software Engineer',
      company: 'TechCorp Solutions • San Francisco, CA',
      period: '2021 - Present',
      current: true,
      description: 'Leading the backend migration from monolith to microservices using Go and gRPC. Improved system throughput by 40% and reduced latency by 25%. Mentoring junior developers and conducting code reviews.',
      skills: ['Golang', 'Kubernetes', 'AWS']
    },
    {
      title: 'Software Developer',
      company: 'Innovate Web Agency • Austin, TX',
      period: '2018 - 2021',
      current: false,
      description: 'Developed and maintained high-traffic e-commerce websites for various clients. Integrated third-party payment gateways (Stripe, PayPal) and implemented responsive designs using React and Tailwind CSS.',
      skills: ['React', 'Node.js', 'PostgreSQL']
    },
    {
      title: 'Junior Developer',
      company: 'StartUp Inc • Remote',
      period: '2016 - 2018',
      current: false,
      description: 'Assisted in the development of the company\'s internal dashboard tools. Collaborated with the design team to implement UI components and fix frontend bugs.',
      skills: ['JavaScript', 'HTML/CSS', 'Git']
    }
  ];

  const education = [
    {
      degree: 'Master of Science in Computer Science',
      school: 'Stanford University',
      period: '2018 - 2020',
      description: 'Specialized in Artificial Intelligence and Distributed Systems. Published a thesis on "Efficient Data Replication in Geo-Distributed Databases".'
    },
    {
      degree: 'Bachelor of Science in Software Engineering',
      school: 'Massachusetts Institute of Technology (MIT)',
      period: '2014 - 2018',
      description: 'Graduated Cum Laude. Member of the Robotics Club and ACM Student Chapter.'
    }
  ];

  const skills = {
    languages: ['JavaScript (ES6+)', 'TypeScript', 'Python', 'Golang', 'HTML5/CSS3'],
    frameworks: ['React', 'Next.js', 'Node.js', 'Tailwind CSS'],
    tools: ['Docker', 'AWS', 'Git/GitHub']
  };

  const awards = [
    {
      title: 'AWS Certified Solutions Architect',
      organization: 'Amazon Web Services • 2022',
      icon: 'military_tech',
      color: 'yellow'
    },
    {
      title: 'Certified Kubernetes Admin (CKA)',
      organization: 'Linux Foundation • 2021',
      icon: 'verified',
      color: 'blue'
    },
    {
      title: 'Employee of the Quarter',
      organization: 'TechCorp Solutions • Q3 2022',
      icon: 'emoji_events',
      color: 'purple'
    }
  ];
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.5
      }
    }
  };

  return (
    <motion.div
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, amount: 0.1 }}
      variants={containerVariants}
      className="px-6 py-10 md:px-12 md:py-14"
    >
      {/* Page Header */}
      <motion.header
        variants={itemVariants}
        className="flex flex-wrap items-center justify-between gap-6 mb-12"
      >
        <div>
          <h2 className="text-3xl md:text-4xl font-black tracking-tight text-slate-900 dark:text-white mb-2">
            My Resume
          </h2>
          <p className="text-slate-600 dark:text-[#92adc9] text-sm md:text-base max-w-lg">
            Passionate Full Stack Developer with 5+ years of experience building scalable web applications and distributed systems.
          </p>
        </div>
        <motion.button
          whileHover={{ scale: 1.05, y: -2 }}
          whileTap={{ scale: 0.95 }}
          className="inline-flex items-center justify-center gap-2 bg-primary hover:bg-blue-600 text-white font-bold py-2.5 px-6 rounded-lg transition-all shadow-lg hover:shadow-primary/25 active:scale-95"
        >
          <span className="material-symbols-outlined text-[20px]">download</span>
          <span>Download PDF</span>
        </motion.button>
      </motion.header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        {/* Left Column (Timeline Content) */}
        <div className="lg:col-span-8 flex flex-col gap-12">
          {/* Work Experience Section */}
          <motion.section variants={itemVariants}>
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 rounded-lg bg-blue-100 dark:bg-[#1e293b] text-primary">
                <span className="material-symbols-outlined">work</span>
              </div>
              <h3 className="text-xl font-bold text-slate-900 dark:text-white">Work Experience</h3>
            </div>
            <div className="relative border-l-2 border-slate-200 dark:border-[#233648] ml-4 space-y-10 pb-4">
              {workExperience.map((job, index) => (
                <motion.div
                  key={index}
                  variants={itemVariants}
                  whileHover={{ x: 5 }}
                  className="pl-8 relative group"
                >
                  <motion.div
                    whileHover={{ scale: 1.2 }}
                    className={`absolute -left-[9px] top-1.5 h-4 w-4 rounded-full border-2 border-white dark:border-[#111a22] ${
                      job.current ? 'bg-primary' : 'bg-slate-300 dark:bg-[#324d67] group-hover:bg-primary'
                    } transition-colors`}
                  />
                  <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start mb-2 gap-1">
                    <h4 className="text-lg font-bold text-slate-900 dark:text-white">{job.title}</h4>
                    <span className={`text-xs font-semibold px-2 py-1 rounded whitespace-nowrap ${
                      job.current 
                        ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400'
                        : 'bg-slate-100 dark:bg-[#1e293b] text-slate-500 dark:text-slate-400'
                    }`}>
                      {job.period}
                    </span>
                  </div>
                  <div className="text-sm font-semibold text-primary mb-3">{job.company}</div>
                  <p className="text-slate-600 dark:text-[#92adc9] text-sm leading-relaxed mb-3">
                    {job.description}
                  </p>
                  <div className="flex flex-wrap gap-2">
                    {job.skills.map((skill, skillIndex) => (
                      <motion.span
                        key={skillIndex}
                        whileHover={{ scale: 1.05 }}
                        className="text-xs font-medium px-2 py-1 rounded bg-slate-100 dark:bg-[#233648] text-slate-600 dark:text-slate-300"
                      >
                        {skill}
                      </motion.span>
                    ))}
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.section>
          {/* Education Section */}
          <motion.section variants={itemVariants}>
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 rounded-lg bg-blue-100 dark:bg-[#1e293b] text-primary">
                <span className="material-symbols-outlined">school</span>
              </div>
              <h3 className="text-xl font-bold text-slate-900 dark:text-white">Education</h3>
            </div>
            <div className="relative border-l-2 border-slate-200 dark:border-[#233648] ml-4 space-y-10 pb-4">
              {education.map((edu, index) => (
                <motion.div
                  key={index}
                  variants={itemVariants}
                  whileHover={{ x: 5 }}
                  className="pl-8 relative group"
                >
                  <motion.div
                    whileHover={{ scale: 1.2 }}
                    className="absolute -left-[9px] top-1.5 h-4 w-4 rounded-full border-2 border-white dark:border-[#111a22] bg-slate-300 dark:bg-[#324d67] group-hover:bg-primary transition-colors"
                  />
                  <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start mb-1 gap-1">
                    <h4 className="text-lg font-bold text-slate-900 dark:text-white">{edu.degree}</h4>
                    <span className="text-xs font-semibold px-2 py-1 rounded bg-slate-100 dark:bg-[#1e293b] text-slate-500 dark:text-slate-400 whitespace-nowrap">
                      {edu.period}
                    </span>
                  </div>
                  <div className="text-sm font-semibold text-primary mb-2">{edu.school}</div>
                  <p className="text-slate-600 dark:text-[#92adc9] text-sm leading-relaxed">
                    {edu.description}
                  </p>
                </motion.div>
              ))}
            </div>
          </motion.section>
        </div>

        {/* Right Column (Skills & Awards) */}
        <div className="lg:col-span-4 flex flex-col gap-10">
          {/* Skills Section */}
          <motion.div
            variants={itemVariants}
            whileHover={{ y: -2 }}
            className="bg-white dark:bg-[#1e293b] rounded-xl p-6 shadow-sm border border-slate-100 dark:border-none"
          >
            <div className="flex items-center gap-2 mb-4">
              <span className="material-symbols-outlined text-primary">code</span>
              <h3 className="text-lg font-bold text-slate-900 dark:text-white">Technical Skills</h3>
            </div>
            <div className="space-y-4">
              <div>
                <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Languages</h4>
                <div className="flex flex-wrap gap-2">
                  {skills.languages.map((lang, index) => (
                    <motion.span
                      key={index}
                      whileHover={{ scale: 1.05 }}
                      className="px-3 py-1 bg-slate-100 dark:bg-[#111a22] text-slate-700 dark:text-slate-300 rounded-full text-sm hover:bg-slate-200 dark:hover:bg-[#233648] transition-colors cursor-default"
                    >
                      {lang}
                    </motion.span>
                  ))}
                </div>
              </div>
              <div>
                <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Frameworks & Libs</h4>
                <div className="flex flex-wrap gap-2">
                  {skills.frameworks.map((framework, index) => (
                    <motion.span
                      key={index}
                      whileHover={{ scale: 1.05 }}
                      className="px-3 py-1 bg-slate-100 dark:bg-[#111a22] text-slate-700 dark:text-slate-300 rounded-full text-sm hover:bg-slate-200 dark:hover:bg-[#233648] transition-colors cursor-default"
                    >
                      {framework}
                    </motion.span>
                  ))}
                </div>
              </div>
              <div>
                <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Tools & DevOps</h4>
                <div className="flex flex-wrap gap-2">
                  {skills.tools.map((tool, index) => (
                    <motion.span
                      key={index}
                      whileHover={{ scale: 1.05 }}
                      className="px-3 py-1 bg-slate-100 dark:bg-[#111a22] text-slate-700 dark:text-slate-300 rounded-full text-sm hover:bg-slate-200 dark:hover:bg-[#233648] transition-colors cursor-default"
                    >
                      {tool}
                    </motion.span>
                  ))}
                </div>
              </div>
            </div>
          </motion.div>
          {/* Awards & Certifications */}
          <motion.div variants={itemVariants}>
            <div className="flex items-center gap-2 mb-4">
              <span className="material-symbols-outlined text-primary">workspace_premium</span>
              <h3 className="text-lg font-bold text-slate-900 dark:text-white">Awards & Certifications</h3>
            </div>
            <div className="grid gap-3">
              {awards.map((award, index) => (
                <motion.div
                  key={index}
                  whileHover={{ y: -4, scale: 1.02 }}
                  className="bg-white dark:bg-[#1e293b] p-4 rounded-xl shadow-sm border border-slate-100 dark:border-none flex items-start gap-4 hover:-translate-y-1 transition-transform duration-200"
                >
                  <div className={`flex-shrink-0 p-2 rounded-lg ${
                    award.color === 'yellow' ? 'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-600 dark:text-yellow-400' :
                    award.color === 'blue' ? 'bg-blue-100 dark:bg-blue-900/30 text-primary' :
                    'bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400'
                  }`}>
                    <span className="material-symbols-outlined text-[24px]">{award.icon}</span>
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-slate-900 dark:text-white">{award.title}</h4>
                    <p className="text-xs text-slate-500 dark:text-[#92adc9] mt-0.5">{award.organization}</p>
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.div>

          {/* Language Skills */}
          <motion.div
            variants={itemVariants}
            whileHover={{ scale: 1.02 }}
            className="bg-gradient-to-br from-primary to-blue-600 rounded-xl p-6 text-white shadow-lg"
          >
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
              <span className="material-symbols-outlined">translate</span>
              Languages
            </h3>
            <div className="space-y-3">
              <div className="flex justify-between items-end">
                <span className="text-sm font-medium">English</span>
                <span className="text-xs opacity-80">Native</span>
              </div>
              <div className="w-full bg-black/20 rounded-full h-1.5">
                <motion.div
                  initial={{ width: 0 }}
                  whileInView={{ width: '100%' }}
                  transition={{ duration: 1, delay: 0.5 }}
                  className="bg-white h-1.5 rounded-full"
                />
              </div>
              <div className="flex justify-between items-end mt-2">
                <span className="text-sm font-medium">Spanish</span>
                <span className="text-xs opacity-80">Professional</span>
              </div>
              <div className="w-full bg-black/20 rounded-full h-1.5">
                <motion.div
                  initial={{ width: 0 }}
                  whileInView={{ width: '80%' }}
                  transition={{ duration: 1, delay: 0.7 }}
                  className="bg-white h-1.5 rounded-full"
                />
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    </motion.div>
  );
};

export default Resume;
